// Account placement, task notifications, completion states, and template search.
state.notificationsOpen=false;
function lineIcon(kind){return kind==='search'?'<svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m15.5 15.5 5 5"/></svg>':'<svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M18 8a6 6 0 0 0-12 0v5l-2 4h16l-2-4z M10 21h4"/></svg>'}
function notificationTasks(){return [{label:'발송 실패 확인',detail:'루미에르 성수 팝업',count:state.retried?0:5,status:'진행 중'},{label:'시안 의견 확인',detail:'노바홈 가전박람회',count:2,status:'검토 중'},{label:'게시 준비',detail:'그린데이 가을 신제품',count:1,status:'시작 예정'}].filter(t=>t.count>0)}
function notificationToolbar(){const tasks=notificationTasks();return `<div class="top-actions task-notifications"><button class="notification-button" data-action="task-notifications" aria-label="확인할 작업" aria-expanded="${state.notificationsOpen}" aria-controls="task-popover">${lineIcon('bell')}${tasks.length?'<i class="notification-dot"></i>':''}</button>${state.notificationsOpen?`<section id="task-popover" class="task-popover" aria-label="확인할 작업"><div class="panel-head"><h2>확인할 작업</h2><button data-action="task-notifications" aria-label="닫기">${uiIcon('close')}</button></div>${tasks.length?tasks.map(t=>`<button class="notification-task" data-task-status="${t.status}"><span><strong>${t.label}</strong><small>${t.detail}</small></span><b>${t.count}</b></button>`).join(''):'<p class="mini-label">확인할 작업이 없습니다.</p>'}<a class="text-link" href="#home" data-dismiss-notifications>홈에서 보기</a></section>`:''}</div>`}
const accountShell=shell;shell=function(body){return accountShell(body).replace('<div class="agency">스테이지원 커뮤니케이션</div>','').replace('<button data-action="usage" class="text-link plan">구독·사용량</button>',`<section class="organization-card"><div class="organization-name">스테이지원 커뮤니케이션</div><div class="organization-plan"><span>Agency 플랜</span><small>구독 중</small></div><button class="text-link" data-action="usage">구독·사용량</button></section>`).replace('<div class="top-actions"><div class="avatar">서</div></div>',notificationToolbar())};
function stageCompletion(){const imported=state.approved||state.published;return {editor:!!(imported||(state.settings.designSaved&&state.consent)),review:!!(approvalCurrent()||state.published),publish:!!state.published,operate:!!state.ended,report:!!state.reportPublished}}
const coloredSteps=steps;steps=function(active){let h=coloredSteps(active);if(state.gameDraftMode)return h;const done=stageCompletion();return h.replace(/class="step ([^"]*)" data-event-step="([^"]+)"/g,(_,cls,r)=>`class="step ${cls} ${done[r]?'completed':''}" data-event-step="${r}" ${done[r]?'aria-label="'+({editor:'제작',review:'검토',publish:'게시',operate:'운영',report:'성과'})[r]+' 완료"':''}`)};
const importedWork=openWorkspaceEvent;openWorkspaceEvent=function(n){importedWork(n);if(['검토 중','시작 예정','진행 중','종료'].includes(n.dataset.eventStatus))state.settings.designSaved=true;retainEvent();render()};
const saveWorkAction=action;action=function(a,n){if(a==='task-notifications'){state.notificationsOpen=!state.notificationsOpen;render();return}if(a==='save'&&!state.prizeError)state.settings.designSaved=true;saveWorkAction(a,n)};
const templateCopy=templates;templates=function(){return templateCopy().replace(/placeholder="예: 박람회에서 가을에[\s\S]*?">/,`placeholder="가을 리빙 박람회에서 사용할 룰렛을 만들어줘. 따뜻한 오렌지와 크림색으로 구성하고, 5개의 보기에 머그컵, 에코백, 커피 쿠폰, 할인 쿠폰, 꽝을 넣어줘.">`).replace('<span class="mini-label">게임 조건을 입력하면 초안이 편집기로 열립니다.</span>','<span class="mini-label">초안은 만든 뒤 수정할 수 있어요.</span>').replace('<p class="sub">자연어로 조건을 알려주세요. 맞는 템플릿을 바탕으로 게임 초안을 만듭니다.</p>','').replace(/<input class="gallery-search" id="template-search"[^>]*>/,m=>`<form id="template-search-form" class="template-search-form" role="search">${m}<button type="submit" aria-label="템플릿 검색">${lineIcon('search')}</button></form>`)};
// Accept realistic "보기에 … 넣어줘" examples while preserving the earlier phrasing.
const richerPrompt=parseGamePrompt;parseGamePrompt=function(p){let normalized=p;const m=p.match(/(?:\d+\s*개(?:의)?\s*)?보기(?:에|는)\s*(.+?)(?=을?\s*넣어|를?\s*넣어|로\s*구성|[.!?。]|$)/);if(m)normalized=p.replace(m[0],'선물은 '+m[1].replace(/(?:을|를)\s*$/,'')+'이 있어');return richerPrompt(normalized)};
const completionBind=bind;bind=function(){completionBind();app.querySelectorAll('[data-task-status]').forEach(n=>n.onclick=()=>{state.notificationsOpen=false;const e=eventData.find(v=>v[2]===n.dataset.taskStatus);if(e)openWorkspaceEvent({dataset:{eventBrand:brands.find(b=>b.short===e[1]).id,openEvent:e[0],eventStatus:e[2]}})});app.querySelectorAll('[data-dismiss-notifications]').forEach(n=>n.onclick=()=>{state.notificationsOpen=false;go('home')});const form=document.getElementById('template-search-form');if(form)form.onsubmit=e=>{e.preventDefault();state.templateSearch=document.getElementById('template-search').value.trim();document.getElementById('template-grid').innerHTML=galleryCards();bind()};const consent=document.getElementById('consent-check');if(consent){const fn=consent.onchange;consent.onchange=()=>{fn();if(!consent.checked)invalidateApproval();render()}}};
if(document.addEventListener){document.addEventListener('click',e=>{if(state.notificationsOpen&&!e.target.closest('.task-notifications')){state.notificationsOpen=false;render()}});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&state.notificationsOpen){state.notificationsOpen=false;render();app.querySelector('.notification-button')?.focus()}})}
render();
const completionAction=action;action=function(a,n){completionAction(a,n);if(a==='save'&&!state.prizeError)render();if(a==='share-report'&&route()==='brand-report'){state.settings.reportShared=true;retainEvent();render()}};
const perEventCompletion=stageCompletion;stageCompletion=function(){const result=perEventCompletion();result.report=!!state.settings.reportShared;return result};
render();
